import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contributing | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/contributing"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/contributing"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/contributing"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/dev/contributing"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/contributing"}]]},"headers":[],"relativePath":"xclang/dev/contributing.md","filePath":"en/xclang/dev/contributing.md","lastUpdated":1791227177000}'),n={name:"xclang/dev/contributing.md"};function l(o,e,c,r,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>xclang is a small repository that drives a large build: LLVM, built six times with PGO and ThinLTO, plus six targets&#39; runtimes. Most contributions are to the scripts, the build integrations, the tests or the docs, and most of them are checked on CI, not on a laptop.</p><h2 id="where-things-are" tabindex="-1">Where things are <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;Where things are&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripts/           TypeScript, run by Node 24: bootstrap, runtimes and</span></span>
<span class="line"><span>                   sysroots, toolchain, package, conda, bazel, cli</span></span>
<span class="line"><span>cmake/caches/      what each LLVM build is</span></span>
<span class="line"><span>config/            the per-target clang config files</span></span>
<span class="line"><span>pgo/               the PGO training and remap.txt</span></span>
<span class="line"><span>windows/alias.c    the launcher behind every name of llvm.exe</span></span>
<span class="line"><span>patches/           changes to LLVM, a directory and a README each</span></span>
<span class="line"><span>packages/          the Bazel module, the CMake package, the conda scripts</span></span>
<span class="line"><span>cli/               the xclang command, in Rust</span></span>
<span class="line"><span>tests/             smoke.ts, libclang.ts, cmake.ts, bazel.ts, ...</span></span>
<span class="line"><span>examples/          the projects the docs show</span></span>
<span class="line"><span>docs/en/           this site</span></span>
<span class="line"><span>.github/workflows/ CI; main.yml runs a release&#39;s stages</span></span></code></pre></div><p><a href="./../design/release-build">How a release is built</a> has the stages and the workflows.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>The builds need CI-sized machines: a full release run is about three hours on GitHub-hosted runners, the toolchain stage about two hours per host. Run them on CI, on a branch of your own:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stages=runtimes,instrumented,train,toolchain,asan,package,test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revision=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>reuse-run</code> (with <code>runtimes-run</code>, <code>profile-run</code>) takes a stage&#39;s artifacts from an earlier run instead of building them again; a toolchain without PGO is enough for most A/B checks. <code>pixi run &lt;task&gt;</code> runs a stage the way CI does (pixi.toml), on a machine that can take it.</p><p>What is cheap locally:</p><ul><li><code>npm install &amp;&amp; npm run check</code>: TypeScript type checks of scripts/ and tests/.</li><li><code>node tests/docs.ts</code>: the docs&#39; code blocks against examples/.</li><li><code>cd cli &amp;&amp; cargo test</code>: the xclang command&#39;s unit tests.</li><li>A patch: <code>patch -p1 -F0 --dry-run</code> against the LLVM release source, and compiling the patched file against a release&#39;s headers (<a href="./llvm-patches">patching LLVM</a>).</li><li>Anything against a released toolchain: unpack an archive and use it.</li></ul><h2 id="style" tabindex="-1">Style <a class="header-anchor" href="#style" aria-label="Permalink to &quot;Style&quot;">​</a></h2><ul><li>Scripts are TypeScript on Node, not Python or shell; comments are <code>///</code> lines.</li><li>Docs and comments say what is and why, plainly: no marketing adjectives, reasons and evidence instead. A claim about behaviour names the test that checks it.</li><li>Commit subjects are <code>&lt;area&gt;: &lt;what changed&gt;</code> (<code>bazel: ...</code>, <code>docs: ...</code>, <code>patches: ...</code>); the body says why.</li><li>Every user-visible change gets a line in CHANGELOG.md&#39;s Unreleased section.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Every change comes with the check that shows it works, on the hosts it touches:</p><table tabindex="0"><thead><tr><th>change</th><th>test</th></tr></thead><tbody><tr><td>the toolchain, the runtimes, a patch</td><td>tests/smoke.ts (main.yml&#39;s <code>test</code> stage, every host)</td></tr><tr><td>libclang</td><td>tests/libclang.ts</td></tr><tr><td>the CMake package</td><td>tests/cmake (cmake.yml)</td></tr><tr><td>the Bazel module</td><td>tests/bazel, tests/bazel.ts, tests/bazel-cross.ts (bazel.yml)</td></tr><tr><td>the xclang command</td><td>tests/cli.ts, tests/cargo.ts (cli.yml)</td></tr><tr><td>the docs&#39; commands, examples/</td><td>examples.yml</td></tr></tbody></table><h2 id="the-docs" tabindex="-1">The docs <a class="header-anchor" href="#the-docs" aria-label="Permalink to &quot;The docs&quot;">​</a></h2><p>The docs are <code>docs/en/&lt;group&gt;/&lt;page&gt;.md</code>, published to <a href="https://docs.clice.io/xclang" target="_blank" rel="noreferrer">docs.clice.io/xclang</a> by clice-io/docs&#39;s sync action when <code>main</code> changes; <code>docs/en/sidebar.yaml</code> orders the pages. To preview, copy <code>docs/en</code> into a checkout of <a href="https://github.com/clice-io/docs" target="_blank" rel="noreferrer">clice-io/docs</a> as <code>en/xclang</code> and run its VitePress build (<code>npm install &amp;&amp; npm run build</code>); the build fails on a dead link. A code block under <code>&lt;!-- file: &lt;path&gt; --&gt;</code> must be that file of the repository, which tests/docs.ts checks.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Bugs and questions: <a href="https://github.com/clice-io/xclang/issues" target="_blank" rel="noreferrer">GitHub issues</a>. A bug in clang, lld or libc++ itself is reported upstream, to LLVM; xclang carries a fix as a patch until upstream has one. Security issues: see <a href="https://github.com/clice-io/xclang/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p>`,20)])])}const u=t(n,[["render",l]]);export{g as __pageData,u as default};
